{
  "items": [
    {
      "name": "Finsupp.support_mapRange",
      "type": " {α : Type u_1} {M : Type u_4} {N : Type u_5} [Zero M] [Zero N] {f : M → N} {hf : f 0 = 0} {g : α →₀ M} : (Finsupp.mapRange f hf g).support ⊆ g.support",
      "module": "Mathlib.Data.Finsupp.Defs"
    },
    {
      "name": "Finsupp.support_subset_iff",
      "type": " {α : Type u_1} {M : Type u_4} [Zero M] {s : Set α} {f : α →₀ M} : ↑f.support ⊆ s ↔ ∀ a ∉ s, f a = 0",
      "module": "Mathlib.Data.Finsupp.Defs"
    },
    {
      "name": "Finsupp.support_zipWith",
      "type": " {α : Type u_1} {M : Type u_4} {N : Type u_5} {O : Type u_6} [Zero M] [Zero N] [Zero O] [D : DecidableEq α] {f : M → N → O} {hf : f 0 0 = 0} {g₁ : α →₀ M} {g₂ : α →₀ N} : (Finsupp.zipWith f hf g₁ g₂).support ⊆ g₁.support ∪ g₂.support",
      "module": "Mathlib.Data.Finsupp.Defs"
    },
    {
      "name": "Finsupp.card_support_le_one'",
      "type": " {α : Type u_1} {M : Type u_4} [Zero M] [Nonempty α] {f : α →₀ M} : f.support.card ≤ 1 ↔ ∃ a b, f = fun₀ | a => b",
      "module": "Mathlib.Data.Finsupp.Single"
    },
    {
      "name": "Finsupp.support_update_subset",
      "type": " {α : Type u_1} {M : Type u_4} [Zero M] (f : α →₀ M) (a : α) {b : M} [DecidableEq α] : (f.update a b).support ⊆ insert a f.support",
      "module": "Mathlib.Data.Finsupp.Single"
    }
  ]
}
